import { calculateShipping } from './shipping';

describe('calculateShipping', () => {
  it('calculates domestic standard shipping for 2kg package', () => {
    expect(calculateShipping(2, 'domestic', false)).toBe(8); // 5 + 2*1.5
  });

  it('calculates international express shipping for 0.5kg package', () => {
    expect(calculateShipping(0.5, 'international', true)).toBe(29); // 25 + 0.5*8 + 10
